{
    "type": "object",
    "properties": {
        "model_name": {
            "type": "string",
            "description": "Odoo technical model name, e.g. res.partner, sale.order, crm.lead, project.task, hr.employee"
        }
    },
    "required": ["model_name"]
}

if model_name not in env:
    ai['result'] = f"ERROR: Model '{model_name}' does not exist in Odoo."
else:
    fields = env[model_name].fields_get(
        attributes=['string', 'type', 'required', 'selection', 'relation', 'help', 'readonly']
    )
    try:
        defaults = env[model_name].default_get(list(fields.keys()))
    except Exception:
        defaults = {}

    SKIP_FIELDS = {
        'id', 'create_uid', 'create_date', 'write_uid', 'write_date',
        'message_ids', 'message_follower_ids', 'activity_ids',
        '__last_update', 'display_name', 'access_token',
    }
    SKIP_TYPES = {'one2many', 'binary', 'reference'}

    required_lines = []
    optional_lines = []
    auto_lines = []

    for fname, fdef in fields.items():
        if fname in SKIP_FIELDS:
            continue
        if fdef['type'] in SKIP_TYPES:
            continue
        if fdef.get('readonly'):
            continue

        line = f"  {fname} | {fdef['string']} | {fdef['type']}"
        if fdef['type'] == 'many2one':
            line += f" -> {fdef.get('relation', '')} | use many2one_field_names"
        if fdef['type'] == 'selection':
            opts = [str(v) for v, _ in (fdef.get('selection') or [])]
            line += f" | options: [{', '.join(opts)}]"

        has_default = fname in defaults and defaults[fname] not in (False, None, '')
        if fdef.get('required') and has_default:
            auto_lines.append(line)
        elif fdef.get('required'):
            required_lines.append(line)
        elif len(optional_lines) < 20:
            optional_lines.append(line)

    output = f"Model: {model_name}\nFormat: field_name | label | type | notes\n"
    output += "\nREQUIRED FIELDS (you MUST provide these):\n"
    output += "\n".join(required_lines) if required_lines else "  (none)"
    output += "\n\nAUTO-GENERATED FIELDS (system fills them — do NOT provide unless the user explicitly gave a value; document numbers like sale order names come from sequences):\n"
    output += "\n".join(auto_lines) if auto_lines else "  (none)"
    output += "\n\nCOMMON OPTIONAL FIELDS:\n"
    output += "\n".join(optional_lines) if optional_lines else "  (none)"

    ai['result'] = output

{
    "type": "object",
    "properties": {
        "model_name": {
            "type": "string",
            "description": "Odoo technical model name, e.g. res.partner, crm.lead, sale.order.line"
        },
        "field_names": {
            "type": "array",
            "description": "List of Odoo technical field names to set. Must match field_values by index. E.g. ['name', 'email', 'order_id', 'product_uom_qty']",
            "items": {"type": "string"}
        },
        "field_values": {
            "type": "array",
            "description": "List of values corresponding to field_names. Same order and length. All as strings: booleans as 'true'/'false', numbers as '10', known database IDs as '5'. E.g. ['John', 'john@test.com', '1', '10']",
            "items": {"type": "string"}
        },
        "many2one_field_names": {
            "type": "array",
            "description": "List of Many2one field names where you only have a display name (system will resolve to ID). E.g. ['partner_id', 'product_id']. Empty array if none.",
            "items": {"type": "string"}
        },
        "many2one_search_names": {
            "type": "array",
            "description": "List of display names to search for, matching many2one_field_names by index. E.g. ['李强', 'Product2']",
            "items": {"type": "string"}
        },
        "many2one_create_flags": {
            "type": "array",
            "description": "For each many2one_field_names entry: 'false' = never create; 'true' = create when not found AND nothing similar exists (user approved creating); 'force' = create even though similar records exist — ONLY after the user saw the similar list and explicitly chose a new record. Same order and length as many2one_field_names.",
            "items": {"type": "string"}
        },
        "force_create": {
            "type": "string",
            "description": "'false' normally. The tool BLOCKS creation when a record with the same name already exists (master data like customers/products). Retry with 'true' ONLY after the user saw the existing record and explicitly wants a duplicate."
        }
    },
    "required": ["model_name", "field_names", "field_values", "many2one_field_names", "many2one_search_names", "many2one_create_flags", "force_create"]
}

if model_name not in env:
    ai['result'] = f"ERROR: Model '{model_name}' does not exist."
elif len(field_names or []) != len(field_values or []):
    ai['result'] = (
        f"ERROR: field_names has {len(field_names or [])} items but field_values has "
        f"{len(field_values or [])} — they must match one-to-one by index. Fix the arrays and retry."
    )
elif len(many2one_field_names or []) != len(many2one_search_names or []):
    ai['result'] = "ERROR: many2one_field_names and many2one_search_names must have the same length. Fix the arrays and retry."
elif model_name in ('hr.payslip', 'hr.payslip.line', 'hr.payslip.run', 'hr.contract'):
    ai['result'] = "BLOCKED: payroll and contract data is READ-ONLY for AI — changes go through the HR payroll workflow with human approval."
else:
    all_fields = env[model_name].fields_get(
        attributes=['string', 'type', 'required', 'relation', 'readonly']
    )
    try:
        defaults = env[model_name].default_get(list(all_fields.keys()))
    except Exception:
        defaults = {}

    # ── Zip field_names + field_values into dict, auto-cast type ──
    vals = {}
    bad_fields = []
    for fname, fval in zip(field_names or [], field_values or []):
        if fname not in all_fields:
            bad_fields.append(fname)
            continue
        ftype = all_fields[fname]['type']
        if ftype == 'boolean':
            vals[fname] = fval.lower() in ('true', '1', 'yes')
        elif ftype in ('integer', 'many2one'):
            vals[fname] = int(fval) if fval.lstrip('-').isdigit() else fval
        elif ftype in ('float', 'monetary'):
            vals[fname] = float(fval)
        else:
            vals[fname] = fval

    # Sequence-generated document numbers (default 'New' or '/') must never
    # be overridden: drop them so Odoo assigns the real number (e.g. S00042)
    dropped_fields = []
    name_default = defaults.get('name')
    if 'name' in vals and isinstance(name_default, str) and name_default.strip() in ('New', '/'):
        vals.pop('name')
        dropped_fields.append("name (sequence-generated by the system)")

    if bad_fields:
        ai['result'] = (
            f"ERROR: Unknown fields for {model_name}: {bad_fields}\n"
            f"Call 'AI Skill: Get Model Fields' first to see valid field names."
        )
    elif 'name' in all_fields and 'name' not in vals and not defaults.get('name') and not all_fields['name'].get('readonly'):
        # e.g. res.partner: name is enforced by a DB constraint, not by the
        # field definition, so the generic required-check cannot see it
        ai['result'] = (
            f"ERROR: creating a {model_name} record needs a 'name' value and none was provided. "
            "Add 'name' to field_names/field_values — ask the user if you don't know it."
        )
    elif ('name' in vals and 'state' not in all_fields
          and str(force_create).lower() not in ('true', '1', 'yes')
          and (existing_same := env[model_name].search(
              [['name', '=ilike', str(vals['name']).strip()]], limit=1))):
        # Master-data duplicate guard (customers, products...): a record with
        # this exact name already exists — creating another one is almost
        # always a mistake. Documents (with a 'state' field) are exempt.
        ai['result'] = (
            f"BLOCKED to avoid a duplicate: {model_name} '{existing_same.display_name}' "
            f"already exists (ID: {existing_same.id}).\n"
            "Use this existing record instead of creating a new one. Only if the user "
            "explicitly wants ANOTHER record with the same name, retry with force_create='true'."
        )
    else:
        # ── Check required fields the user must really provide ──
        # Readonly/computed fields, x2many/binary fields and fields with a
        # system default (sequences, dates, company...) are filled by Odoo
        # itself: never demand them from the caller.
        SYSTEM_FIELDS = {'id', 'create_uid', 'write_uid', 'create_date', 'write_date', 'active'}
        SKIP_TYPES = {'one2many', 'many2many', 'binary', 'reference'}
        m2o_keys = list(many2one_field_names or [])
        missing = [
            f"{f} ({all_fields[f]['string']}, {all_fields[f]['type']})"
            for f, d in all_fields.items()
            if d.get('required')
            and not d.get('readonly')
            and d['type'] not in SKIP_TYPES
            and f not in SYSTEM_FIELDS
            and f not in vals
            and f not in m2o_keys
            and not (f in defaults and defaults[f] not in (False, None, ''))
        ]
        if missing:
            ai['result'] = (
                f"ERROR: Missing required fields for {model_name}:\n"
                + "\n".join(f"  - {m}" for m in missing)
                + "\nPlease provide these fields and try again."
            )
        else:
            # ── Resolve many2one names to IDs (exact, then fuzzy, then suggest) ──
            resolve_error = None
            created_related = []
            create_flags = [str(f).lower() for f in (many2one_create_flags or [])]
            idx = 0
            for fname, search_name in zip(many2one_field_names or [], many2one_search_names or []):
                flag = create_flags[idx] if idx < len(create_flags) else 'false'
                idx += 1
                allow_create = flag in ('true', '1', 'yes', 'force')
                force_create = flag == 'force'
                search_name = (search_name or '').strip()
                if not fname or not search_name:
                    continue
                if fname not in all_fields:
                    resolve_error = f"ERROR: Field '{fname}' not found in {model_name}."
                    break
                related_model = all_fields[fname].get('relation')
                if not related_model:
                    resolve_error = f"ERROR: '{fname}' is not a Many2one field."
                    break
                Related = env[related_model]
                if related_model == 'product.product':
                    # Variant-aware resolution: 'PVC板(昆明,8mm)' selects the variant
                    # whose attribute values match; plain names must be unambiguous.
                    norm_name = search_name.replace('（', '(').replace('）', ')')
                    base_name = norm_name.split('(')[0].strip() if '(' in norm_name else norm_name.strip()
                    inner_part = norm_name.split('(', 1)[1].split(')')[0] if '(' in norm_name else ''
                    for sep in ('，', '、', '|', '；', ';'):
                        inner_part = inner_part.replace(sep, ',')
                    wanted_vals = [w.strip().lower() for w in inner_part.split(',') if w.strip()]
                    found = Related.search([['default_code', '=ilike', base_name]], limit=1)
                    if not found:
                        p_tmpl = env['product.template'].search([['name', '=ilike', base_name]], limit=1)
                        if not p_tmpl:
                            p_tmpl = env['product.template'].search([['name', 'ilike', base_name]], limit=1)
                        if p_tmpl:
                            cand = p_tmpl.product_variant_ids
                            if wanted_vals:
                                # exact value match first ('5mm' must not hit '15mm'),
                                # substring only as fallback
                                matched = env['product.product']
                                loose = env['product.product']
                                for p in cand:
                                    vname_list = [(n or '').lower() for n in p.product_template_attribute_value_ids.mapped('name')]
                                    exact_ok = True
                                    loose_ok = True
                                    for w in wanted_vals:
                                        if w not in vname_list:
                                            exact_ok = False
                                        hit = False
                                        for n in vname_list:
                                            if w in n:
                                                hit = True
                                                break
                                        if not hit:
                                            loose_ok = False
                                    if exact_ok:
                                        matched += p
                                    if loose_ok:
                                        loose += p
                                cand = matched if matched else loose
                            if len(cand) == 1:
                                found = cand
                            elif len(cand) > 1:
                                cand_names = "; ".join(f"ID {p.id}: {p.display_name}" for p in cand[:12])
                                resolve_error = (
                                    f"ERROR: '{search_name}' matches SEVERAL variants of '{p_tmpl.name}': {cand_names}\n"
                                    "Ask the user which one (quick options), then retry passing the chosen "
                                    "variant ID directly (field_names ['product_id'], field_values ['<id>'])."
                                )
                                break
                            elif wanted_vals:
                                avail = "; ".join(f"ID {p.id}: {p.display_name}" for p in p_tmpl.product_variant_ids[:12])
                                resolve_error = (
                                    f"ERROR: no variant of '{p_tmpl.name}' matches ({inner_part}). Existing variants: {avail}\n"
                                    "If this combination should exist, run 'AI Skill: Configure Product Variants' "
                                    "first to add it, then retry."
                                )
                                break
                else:
                    found = Related.search([['name', '=ilike', search_name]], limit=1)
                    if not found:
                        found = Related.search([['name', 'ilike', search_name]], limit=1)
                if not found and allow_create:
                    # Anti-duplicate guard: even with the create flag, refuse to
                    # create when similar records exist (typos!) unless forced
                    similar_guard = Related.search(
                        [['name', 'ilike', search_name[:max(3, len(search_name) - 2)]]], limit=5
                    )
                    if similar_guard and not force_create:
                        names = ", ".join(similar_guard.mapped('display_name'))
                        resolve_error = (
                            f"BLOCKED to avoid a duplicate: '{search_name}' was not found exactly, "
                            f"but similar records already exist in {related_model}: {names}\n"
                            "Ask the user (quick options): use one of these existing records, or really "
                            "create a new one? Only if they explicitly choose a NEW record, retry with "
                            "this many2one_create_flags entry set to 'force'."
                        )
                        break
                    found = Related.create({'name': search_name})
                    created_related.append(f"{related_model} '{search_name}' (ID: {found.id})")
                if not found:
                    prefix = search_name[:max(3, len(search_name) - 2)]
                    similar = Related.search([['name', 'ilike', prefix]], limit=5)
                    if similar:
                        names = ", ".join(similar.mapped('display_name'))
                        resolve_error = (
                            f"ERROR: Cannot find '{search_name}' in {related_model}.\n"
                            f"Similar existing records: {names}\n"
                            "Ask the user which one to use (present them as quick options), "
                            "or set the matching many2one_create_flags entry to 'true' if the user wants a new record created."
                        )
                    else:
                        resolve_error = (
                            f"ERROR: Cannot find '{search_name}' in {related_model} and no similar record exists.\n"
                            "Ask the user to confirm the exact name, or whether to create it "
                            "(then set the matching many2one_create_flags entry to 'true')."
                        )
                    break
                vals[fname] = found.id

            if resolve_error:
                ai['result'] = resolve_error
            else:
                record = env[model_name].create(vals)
                extra = ""
                if created_related:
                    extra = "\n  Also created: " + "; ".join(created_related)
                if dropped_fields:
                    extra += "\n  Ignored (auto-generated by the system): " + "; ".join(dropped_fields)
                ai['result'] = (
                    f"Created {model_name} record successfully.\n"
                    f"  ID: {record.id}\n"
                    f"  Name: {record.display_name}"
                    + extra
                )

{
    "type": "object",
    "properties": {
        "model_name": {
            "type": "string",
            "description": "Odoo technical model name, e.g. res.partner, crm.lead, sale.order.line"
        },
        "record_id": {
            "type": "number",
            "description": "Database ID of the record to update. Use 0 if searching by name instead."
        },
        "search_name": {
            "type": "string",
            "description": "Name to search for the record if record_id is 0. Leave empty string if using record_id."
        },
        "field_names": {
            "type": "array",
            "description": "List of Odoo technical field names to update. Must match field_values by index. Empty array if only updating many2one fields.",
            "items": {"type": "string"}
        },
        "field_values": {
            "type": "array",
            "description": "List of new values corresponding to field_names. Same order and length. All as strings.",
            "items": {"type": "string"}
        },
        "many2one_field_names": {
            "type": "array",
            "description": "List of Many2one field names to set by display name, e.g. ['product_id']. Empty array if none.",
            "items": {"type": "string"}
        },
        "many2one_search_names": {
            "type": "array",
            "description": "Display names matching many2one_field_names by index, e.g. ['Product2']",
            "items": {"type": "string"}
        },
        "many2one_create_flags": {
            "type": "array",
            "description": "For each many2one_field_names entry: 'false' = never create; 'true' = create when not found AND nothing similar exists; 'force' = create despite similar records — only after explicit user choice.",
            "items": {"type": "string"}
        }
    },
    "required": ["model_name", "record_id", "search_name", "field_names", "field_values", "many2one_field_names", "many2one_search_names", "many2one_create_flags"]
}

if model_name not in env:
    ai['result'] = f"ERROR: Model '{model_name}' does not exist."
elif not (field_names or many2one_field_names):
    ai['result'] = "ERROR: Nothing to update: provide field_names or many2one_field_names."
elif len(field_names or []) != len(field_values or []):
    ai['result'] = (
        f"ERROR: field_names has {len(field_names or [])} items but field_values has "
        f"{len(field_values or [])} — they must match one-to-one by index. Fix the arrays and retry."
    )
elif len(many2one_field_names or []) != len(many2one_search_names or []):
    ai['result'] = "ERROR: many2one_field_names and many2one_search_names must have the same length. Fix the arrays and retry."
elif model_name in ('hr.payslip', 'hr.payslip.line', 'hr.payslip.run', 'hr.contract'):
    ai['result'] = "BLOCKED: payroll and contract data is READ-ONLY for AI — changes go through the HR payroll workflow with human approval."
else:
    all_fields = env[model_name].fields_get(
        attributes=['string', 'type', 'relation']
    )

    # ── Zip field_names + field_values into dict, auto-cast type ──
    vals = {}
    bad_fields = []
    for fname, fval in zip(field_names or [], field_values or []):
        if fname not in all_fields:
            bad_fields.append(fname)
            continue
        ftype = all_fields[fname]['type']
        if ftype == 'boolean':
            vals[fname] = fval.lower() in ('true', '1', 'yes')
        elif ftype in ('integer', 'many2one'):
            vals[fname] = int(fval) if fval.lstrip('-').isdigit() else fval
        elif ftype in ('float', 'monetary'):
            vals[fname] = float(fval)
        else:
            vals[fname] = fval

    # ── Resolve many2one names to IDs (exact, then fuzzy, then suggest) ──
    resolve_error = None
    created_related = []
    create_flags = [str(f).lower() for f in (many2one_create_flags or [])]
    idx = 0
    for fname, m2o_name in zip(many2one_field_names or [], many2one_search_names or []):
        flag = create_flags[idx] if idx < len(create_flags) else 'false'
        idx += 1
        allow_create = flag in ('true', '1', 'yes', 'force')
        force_create = flag == 'force'
        m2o_name = (m2o_name or '').strip()
        if not fname or not m2o_name:
            continue
        if fname not in all_fields:
            resolve_error = f"ERROR: Field '{fname}' not found in {model_name}."
            break
        related_model = all_fields[fname].get('relation')
        if not related_model:
            resolve_error = f"ERROR: '{fname}' is not a Many2one field."
            break
        Related = env[related_model]
        if related_model == 'product.product':
            # Variant-aware resolution: 'PVC板(昆明,8mm)' selects the exact variant
            norm_name = m2o_name.replace('（', '(').replace('）', ')')
            base_name = norm_name.split('(')[0].strip() if '(' in norm_name else norm_name.strip()
            inner_part = norm_name.split('(', 1)[1].split(')')[0] if '(' in norm_name else ''
            for sep in ('，', '、', '|', '；', ';'):
                inner_part = inner_part.replace(sep, ',')
            wanted_vals = [w.strip().lower() for w in inner_part.split(',') if w.strip()]
            found = Related.search([['default_code', '=ilike', base_name]], limit=1)
            if not found:
                p_tmpl = env['product.template'].search([['name', '=ilike', base_name]], limit=1)
                if not p_tmpl:
                    p_tmpl = env['product.template'].search([['name', 'ilike', base_name]], limit=1)
                if p_tmpl:
                    cand = p_tmpl.product_variant_ids
                    if wanted_vals:
                        # exact value match first ('5mm' must not hit '15mm'),
                        # substring only as fallback
                        matched = env['product.product']
                        loose = env['product.product']
                        for p in cand:
                            vname_list = [(n or '').lower() for n in p.product_template_attribute_value_ids.mapped('name')]
                            exact_ok = True
                            loose_ok = True
                            for w in wanted_vals:
                                if w not in vname_list:
                                    exact_ok = False
                                hit = False
                                for n in vname_list:
                                    if w in n:
                                        hit = True
                                        break
                                if not hit:
                                    loose_ok = False
                            if exact_ok:
                                matched += p
                            if loose_ok:
                                loose += p
                        cand = matched if matched else loose
                    if len(cand) == 1:
                        found = cand
                    elif len(cand) > 1:
                        cand_names = "; ".join(f"ID {p.id}: {p.display_name}" for p in cand[:12])
                        resolve_error = (
                            f"ERROR: '{m2o_name}' matches SEVERAL variants of '{p_tmpl.name}': {cand_names}\n"
                            "Ask the user which one (quick options), then retry passing the chosen "
                            "variant ID directly."
                        )
                        break
                    elif wanted_vals:
                        avail = "; ".join(f"ID {p.id}: {p.display_name}" for p in p_tmpl.product_variant_ids[:12])
                        resolve_error = (
                            f"ERROR: no variant of '{p_tmpl.name}' matches ({inner_part}). Existing variants: {avail}\n"
                            "If this combination should exist, run 'AI Skill: Configure Product Variants' "
                            "first to add it, then retry."
                        )
                        break
        else:
            found = Related.search([['name', '=ilike', m2o_name]], limit=1)
            if not found:
                found = Related.search([['name', 'ilike', m2o_name]], limit=1)
        if not found and allow_create:
            similar_guard = Related.search(
                [['name', 'ilike', m2o_name[:max(3, len(m2o_name) - 2)]]], limit=5
            )
            if similar_guard and not force_create:
                names = ", ".join(similar_guard.mapped('display_name'))
                resolve_error = (
                    f"BLOCKED to avoid a duplicate: '{m2o_name}' was not found exactly, "
                    f"but similar records already exist in {related_model}: {names}\n"
                    "Ask the user (quick options): use one of these existing records, or really "
                    "create a new one? Only if they explicitly choose a NEW record, retry with "
                    "this many2one_create_flags entry set to 'force'."
                )
                break
            found = Related.create({'name': m2o_name})
            created_related.append(f"{related_model} '{m2o_name}' (ID: {found.id})")
        if not found:
            prefix = m2o_name[:max(3, len(m2o_name) - 2)]
            similar = Related.search([['name', 'ilike', prefix]], limit=5)
            if similar:
                names = ", ".join(similar.mapped('display_name'))
                resolve_error = (
                    f"ERROR: Cannot find '{m2o_name}' in {related_model}.\n"
                    f"Similar existing records: {names}\n"
                    "Ask the user which one to use (present them as quick options)."
                )
            else:
                resolve_error = (
                    f"ERROR: Cannot find '{m2o_name}' in {related_model} and no similar record exists.\n"
                    "Ask the user to confirm the exact name, or whether to create it."
                )
            break
        vals[fname] = found.id

    if bad_fields:
        ai['result'] = (
            f"ERROR: Unknown fields: {bad_fields}\n"
            f"Call 'AI Skill: Get Model Fields' to see valid field names."
        )
    elif resolve_error:
        ai['result'] = resolve_error
    else:
        target = None
        if record_id:
            target = env[model_name].browse(int(record_id))
            if not target.exists():
                ai['result'] = f"ERROR: No record with ID {record_id} in {model_name}."
                target = None
        elif search_name:
            target = env[model_name].search(
                [['name', 'ilike', search_name]], limit=1
            )
            if not target:
                ai['result'] = f"ERROR: Cannot find '{search_name}' in {model_name}."
                target = None
        else:
            ai['result'] = "ERROR: Provide either record_id or search_name."

        if target and model_name == 'account.move' and target.state != 'draft':
            ai['result'] = (
                f"BLOCKED: {target.display_name} is not a draft (state: {target.state}). "
                "Posted legal documents are never edited directly — reset to draft first "
                "(button_draft, after explicit user confirmation and a warning about the consequences)."
            )
            target = None
        if target:
            # Capture old values so the audit trail shows exactly what changed
            old_values = {}
            for f in vals:
                fdef = all_fields.get(f, {})
                old = target[f]
                if fdef.get('type') == 'many2one':
                    old = old.display_name if old else ''
                old_values[f] = old
            target.write(vals)
            changes = []
            for f in vals:
                fdef = all_fields.get(f, {})
                new = target[f]
                if fdef.get('type') == 'many2one':
                    new = new.display_name if new else ''
                changes.append(f"    {f}: {old_values[f]!r} -> {new!r}")
            extra = ""
            if created_related:
                extra = "\n  Also created: " + "; ".join(created_related)
            ai['result'] = (
                f"Updated {model_name} record successfully.\n"
                f"  ID: {target.id}\n"
                f"  Name: {target.display_name}\n"
                f"  Changes (old -> new):\n" + "\n".join(changes)
                + extra
            )

