            "type": "array",
            "description": "Technical field names to read, e.g. ['name', 'email', 'partner_id', 'amount_total']. Empty array reads common fields (name/display_name).",
            "items": {"type": "string"}
        }
    },
    "required": ["model_name", "record_id", "field_names"]
}

if model_name not in env:
    ai['result'] = f"ERROR: Model '{model_name}' does not exist."
else:
    target = env[model_name].browse(int(record_id))
    if not target.exists():
        ai['result'] = f"ERROR: No record with ID {record_id} in {model_name}."
    else:
        all_fields = env[model_name].fields_get(attributes=['string', 'type'])
        names = [f for f in (field_names or []) if f]
        if not names:
            names = [f for f in ('name', 'display_name') if f in all_fields]
        lines = [f"Record {model_name} ID {target.id} ({target.display_name}):"]
        for fname in names:
            if fname not in all_fields:
                lines.append(f"  {fname}: (unknown field)")
                continue
            value = target[fname]
            ftype = all_fields[fname]['type']
            if ftype == 'many2one':
                value = value.display_name if value else ''
            elif ftype in ('one2many', 'many2many'):
                value = ", ".join(value.mapped('display_name')[:20])
            elif ftype == 'binary':
                value = '(binary)'
            lines.append(f"  {fname} ({all_fields[fname]['string']}): {value}")
        ai['result'] = "\n".join(lines)

