{
    "type": "object",
    "properties": {
        "model_name": {
            "type": "string",
            "description": "Odoo technical model name, e.g. sale.order, purchase.order, account.move, stock.picking"
        },
        "record_id": {
            "type": "number",
            "description": "Database ID of the record."
        },
        "action_name": {
            "type": "string",
            "enum": ["action_confirm", "action_cancel", "action_draft", "action_post", "button_validate", "button_confirm", "button_cancel", "button_draft", "action_create_invoice", "action_assign", "action_approve", "action_validate", "action_refuse", "action_set_won", "action_set_lost"],
            "description": "The whitelisted workflow action to trigger. sale.order uses action_confirm; purchase.order uses button_confirm."
        },
        "expected_name": {
            "type": "string",
            "description": "The document name/reference the user is talking about (e.g. 'S00006', 'INV/2026/00001'). The tool BLOCKS execution if record_id does not match this name — always provide it when known. Empty string to skip the check."
        }
    },
    "required": ["model_name", "record_id", "action_name", "expected_name"]
}

if model_name not in env:
    ai['result'] = f"ERROR: Model '{model_name}' does not exist."
else:
    target = env[model_name].browse(int(record_id))
    if not target.exists():
        ai['result'] = f"ERROR: No record with ID {record_id} in {model_name}."
    elif expected_name and expected_name.strip() and expected_name.strip().lower() not in (target.display_name or '').lower():
        ai['result'] = (
            f"BLOCKED: record mismatch. record_id {target.id} is '{target.display_name}', "
            f"NOT '{expected_name}'. You may be acting on the wrong document — search for the "
            "correct record first and retry with the verified ID."
        )
        target = None
    if target and action_name in ('action_cancel', 'button_cancel'):
        # Irreversibility guards: some cancellations have legal/stock
        # consequences and must go through the manual workflow
        guard_msg = None
        if model_name == 'account.move' and target.state == 'posted':
            guard_msg = (
                "BLOCKED: cancelling a POSTED invoice/bill affects legal and tax records "
                "(credit notes may be required). This must be handled manually by accounting — "
                "tell the user honestly and do not attempt workarounds."
            )
        elif model_name == 'sale.order':
            so_fields = env[model_name].fields_get(['invoice_ids', 'picking_ids'])
            has_posted_inv = 'invoice_ids' in so_fields and any(i.state == 'posted' for i in target.invoice_ids)
            has_done_pick = 'picking_ids' in so_fields and any(p.state == 'done' for p in target.picking_ids)
            if has_posted_inv or has_done_pick:
                guard_msg = (
                    f"BLOCKED: {target.display_name} already has posted invoices and/or done deliveries. "
                    "Cancelling requires credit notes / stock returns — advise handling it in the "
                    "standard UI with finance/warehouse involvement."
                )
        elif model_name == 'purchase.order':
            po_fields = env[model_name].fields_get(['picking_ids'])
            if 'picking_ids' in po_fields and any(p.state == 'done' for p in target.picking_ids):
                guard_msg = (
                    f"BLOCKED: {target.display_name} has received transfers. Cancelling after "
                    "reception requires returns/refunds — advise the manual workflow."
                )
        if guard_msg:
            ai['result'] = guard_msg
            target = None
    if target:
        state_field = 'state' in env[model_name].fields_get(['state'])
        before_name = target.display_name
        before_state = target.state if state_field else ''
        done = False
        if action_name == 'action_confirm':
            target.action_confirm()
            done = True
        elif action_name == 'action_cancel':
            target.action_cancel()
            done = True
        elif action_name == 'action_draft':
            target.action_draft()
            done = True
        elif action_name == 'action_post':
            target.action_post()
            done = True
        elif action_name == 'button_validate':
            target.button_validate()
            done = True
        elif action_name == 'button_confirm':
            target.button_confirm()
            done = True
        elif action_name == 'button_cancel':
            target.button_cancel()
            done = True
        elif action_name == 'button_draft':
            target.button_draft()
            done = True
        elif action_name == 'action_create_invoice':
            target.action_create_invoice()
            done = True
        elif action_name == 'action_assign':
            target.action_assign()
            done = True
        elif action_name == 'action_approve':
            target.action_approve()
            done = True
        elif action_name == 'action_validate':
            target.action_validate()
            done = True
        elif action_name == 'action_refuse':
            target.action_refuse()
            done = True
        elif action_name == 'action_set_won':
            target.action_set_won()
            done = True
        elif action_name == 'action_set_lost':
            target.action_set_lost()
            done = True

        if done:
            after_state = target.state if state_field else ''
            lines = [f"Action '{action_name}' executed on {model_name} (ID: {target.id})."]
            lines.append(f"  Record: {before_name} -> {target.display_name}")
            if state_field:
                lines.append(f"  State: {before_state} -> {after_state}")
                if before_state == after_state:
                    lines.append(
                        "  WARNING: the state did NOT change. The action may have had no effect — "
                        "tell the user honestly and verify with Read Record Details before claiming success."
                    )
            ai['result'] = "\n".join(lines)
        else:
            ai['result'] = f"ERROR: action '{action_name}' is not in the allowed list."

