if model_name not in env:
    ai['result'] = f"ERROR: Model '{model_name}' does not exist."
elif str(preview_only).lower() in ('true', '1', 'yes'):
    channel = env.context.get('discuss_channel')
    if not channel:
        ai['result'] = "ERROR: email preview is only available inside an AI chat conversation."
    else:
        ai['result'] = channel.ai_preview_mail_template(model_name, int(record_id), template_search or '')
else:
    record = env[model_name].browse(int(record_id))
    if not record.exists():
        ai['result'] = f"ERROR: No record with ID {record_id} in {model_name}."
    else:
        # Access probe: template rendering/sending runs with elevated rights
        # internally, so verify the USER may read this document first
        record.check_access('read')
        Template = env['mail.template'].sudo()
        template = None
        if template_search:
            template = Template.search([('model', '=', model_name), ('name', 'ilike', template_search)], limit=1)
        if not template:
            template = Template.search([('model', '=', model_name)], limit=1)
        if not template:
            ai['result'] = (
                f"ERROR: No official email template exists for {model_name}. "
                "Sending free-form emails is not allowed."
            )
        else:
            email_to = ""
            if 'partner_id' in env[model_name].fields_get(['partner_id']):
                partner = record.partner_id
                if partner and not partner.email:
                    email_to = None
                    ai['result'] = (
                        f"ERROR: {partner.display_name} has no email address. "
                        "Ask the user for the email, update the contact first, then retry."
                    )
                elif partner:
                    email_to = partner.email
            if email_to is not None:
                template.send_mail(record.id, force_send=True)
                sent_to = email_to or "the recipients defined by the template"
                ai['result'] = (
                    f"Email sent for {record.display_name}.\n"
                    f"  Template: {template.name}\n"
                    f"  Recipient: {sent_to}"
                )

