                f"ERROR: Invoice {invoice.name} is not posted (state: {invoice.state}). "
                "Post it first with Trigger Record Action (action_post), after asking the user."
            )
        elif invoice.payment_state == 'paid':
            ai['result'] = f"ERROR: Invoice {invoice.name} is already fully paid."
        else:
            wizard_vals = {}
            if amount:
                wizard_vals['amount'] = float(amount)
            wizard = env['account.payment.register'].with_context(
                active_model='account.move', active_ids=invoice.ids,
            ).create(wizard_vals)
            wizard.action_create_payments()
            invoice.invalidate_recordset(['payment_state', 'amount_residual'])
            ai['result'] = (
                f"Payment registered on {invoice.name}.\n"
                f"  Amount paid: {amount or 'full remaining amount'}\n"
                f"  Payment state now: {invoice.payment_state}\n"
                f"  Remaining balance: {invoice.amount_residual}"
            )

{
    "type": "object",
    "properties": {
        "log_id": {
            "type": "number",
            "description": "Audit log ID of the operation to undo (from the list_recent output). Use 0 for the user's most recent undoable operation."
        },
        "list_recent": {
            "type": "string",
            "description": "'true' to only LIST the user's recent undoable operations without changing anything; 'false' to actually perform the undo."
        }
    },
    "required": ["log_id", "list_recent"]
}

UNDOABLE_CREATE = ['AI Skill: Create Record', 'AI Skill: Duplicate Record']
UNDOABLE_ARCHIVE = ['AI Skill: Archive Record']
Log = env['ai.audit.log'].sudo()
base_domain = [
    ('user_id', '=', env.uid),
    ('has_error', '=', False),
    ('undone', '=', False),
    ('target_record_id', '!=', 0),
    ('tool_name', 'in', UNDOABLE_CREATE + UNDOABLE_ARCHIVE),
]

if str(list_recent).lower() in ('true', '1', 'yes'):
    logs = Log.search(base_domain, order='id desc', limit=5)
    if not logs:
        ai['result'] = "No undoable operations found for you. Only your own create/duplicate/archive operations can be undone."
    else:
        lines = ["Your recent undoable operations (newest first):"]
        for log in logs:
            action_hint = "will be ARCHIVED" if log.tool_name in UNDOABLE_CREATE else "will be RESTORED"
            lines.append(
                f"  log_id={log.id} | {log.create_date} | {log.tool_name} | "
                f"{log.target_model} ID {log.target_record_id} | undo = record {action_hint}"
            )
        lines.append("Present these to the user as quick options and confirm before undoing.")
        ai['result'] = "\n".join(lines)
else:
    if log_id:
        log = Log.browse(int(log_id)).exists()
    else:
        log = Log.search(base_domain, order='id desc', limit=1)

    if not log:
        ai['result'] = "ERROR: No matching undoable operation found."
    elif log.user_id.id != env.uid:
        ai['result'] = "ERROR: You can only undo your own operations."
    elif log.undone:
        ai['result'] = "ERROR: This operation was already undone."
    elif log.tool_name not in UNDOABLE_CREATE + UNDOABLE_ARCHIVE or not log.target_record_id:
        ai['result'] = "ERROR: This operation cannot be undone (only create/duplicate/archive are reversible)."
    elif log.target_model not in env:
        ai['result'] = f"ERROR: Model '{log.target_model}' no longer exists."
    else:
        target = env[log.target_model].with_context(active_test=False).browse(log.target_record_id)
        if not target.exists():
            ai['result'] = f"ERROR: Record {log.target_model} ID {log.target_record_id} no longer exists."
        elif 'active' not in env[log.target_model].sudo().fields_get(['active']):
            ai['result'] = f"ERROR: Model {log.target_model} does not support archiving; cannot undo safely."
        else:
            if log.tool_name in UNDOABLE_CREATE:
                target.write({'active': False})
                outcome = "archived (hidden, not destroyed)"
            else:
                target.write({'active': True})
                outcome = "restored"
            log.write({'undone': True})
            ai['result'] = (
                f"Undo successful.\n"
                f"  Operation: {log.tool_name} (log_id={log.id})\n"
                f"  Record: {log.target_model} '{target.display_name}' (ID: {target.id}) was {outcome}."
            )

{
    "type": "object",
    "properties": {
        "product_name": {
            "type": "string",
            "description": "Existing product (template) name or numeric ID, e.g. 'PVC板' or '42'. The product must exist — create it first with Create Record if needed."
        },
        "attribute_names": {
            "type": "array",
            "items": {"type": "string"},
            "description": "Attribute names in order, e.g. ['厂地', '厚度']. Missing attributes are created."
        },
        "attribute_values": {
            "type": "array",
            "items": {"type": "string"},
            "description": "For each attribute (same index as attribute_names), ALL its values in one comma-separated string, e.g. ['昆明,成都', '5mm,8mm,10mm,15mm']. Missing values are created, existing ones reused."
        },
        "uom_name": {
            "type": "string",
            "description": "Optional unit of measure name to set on the product, e.g. '120x240cm'. Found by name, or created as a new independent unit. Empty string to skip."
        }
    },
    "required": ["product_name", "attribute_names", "attribute_values", "uom_name"]
}

pname = (product_name or '').strip()
attr_names = attribute_names or []
attr_value_lists = attribute_values or []
if not pname:
    ai['result'] = "ERROR: product_name is required (name or numeric ID of the product)."
elif len(attr_names) != len(attr_value_lists):
    ai['result'] = "ERROR: attribute_names and attribute_values must be parallel arrays of the same length."
else:
    Tmpl = env['product.template']
    tmpl = None
    if pname.isdigit():
        found_tmpl = Tmpl.browse(int(pname))
        tmpl = found_tmpl if found_tmpl.exists() else None
    if tmpl is None:
        exact = Tmpl.search([['name', '=ilike', pname]], limit=1)
        tmpl = exact if exact else None
    if tmpl is None:
        candidates = Tmpl.search([['name', 'ilike', pname]], limit=5)
        if len(candidates) == 1:
            tmpl = candidates
        elif candidates:
            names = "; ".join(f"ID {c.id}: {c.display_name}" for c in candidates)
            ai['result'] = (
                f"ERROR: several products match '{pname}': {names}\n"
                "Present them to the user as quick options and retry with the chosen ID."
            )
        else:
            ai['result'] = (
                f"ERROR: product '{pname}' not found. Create the product first "
                "(AI Skill: Create Record on product.template), then call this skill again."
            )
    if tmpl is not None and 'result' not in ai:
        summary = []
        for a_name, raw in zip(attr_names, attr_value_lists):
            a_name = (a_name or '').strip()
            raw = raw or ''
            for sep in ('，', '、', '|', '；', ';'):
                raw = raw.replace(sep, ',')
            value_names = [v.strip() for v in raw.split(',') if v.strip()]
            if not a_name or not value_names:
                continue
            attribute = env['product.attribute'].search([['name', '=ilike', a_name]], limit=1)
            attr_note = ""
            if not attribute:
                attribute = env['product.attribute'].create({'name': a_name})
                attr_note = " (new attribute)"
            values = env['product.attribute.value']
            for v_name in value_names:
                value = env['product.attribute.value'].search(
                    [['attribute_id', '=', attribute.id], ['name', '=ilike', v_name]], limit=1)
                if not value:
                    value = env['product.attribute.value'].create(
                        {'attribute_id': attribute.id, 'name': v_name})
                values += value
            line = tmpl.attribute_line_ids.filtered(lambda l: l.attribute_id == attribute)
            if line:
                missing = [v.id for v in values if v.id not in line[0].value_ids.ids]
                if missing:
                    line[0].write({'value_ids': [(4, vid) for vid in missing]})
                    change = f"updated ({len(missing)} value(s) added)"
                else:
                    change = "already configured"
            else:
                env['product.template.attribute.line'].create({
                    'product_tmpl_id': tmpl.id,
                    'attribute_id': attribute.id,
                    'value_ids': [(6, 0, values.ids)],
                })
                change = "linked to the product"
            summary.append(f"  - {attribute.name}{attr_note}: {', '.join(value_names)} — {change}")
        uom_note = ""
        u_name = (uom_name or '').strip()
        if u_name:
            uom = env['uom.uom'].search([['name', '=ilike', u_name]], limit=1)
            if not uom:
                uom = env['uom.uom'].create({'name': u_name})
                uom_note = f"\nUnit of measure: created '{uom.name}' (ID: {uom.id}) and set on the product."
            else:
                uom_note = f"\nUnit of measure: set to existing '{uom.display_name}'."
            tmpl.write({'uom_id': uom.id})
        variants = tmpl.product_variant_ids
        v_lines = [f"  - ID {p.id}: {p.display_name}" for p in variants[:20]]
        more = f"\n  ... and {len(variants) - 20} more" if len(variants) > 20 else ""
        ai['result'] = (
            f"Variants configured on '{tmpl.name}' (template ID: {tmpl.id}).\n"
            + ("\n".join(summary) if summary else "  (no attribute changes)")
            + uom_note
            + f"\n{len(variants)} variant(s) now exist:\n" + "\n".join(v_lines) + more
            + "\nTo put one on an order line, use the variant ID directly, or the "
            + "'名称(属性值1,属性值2)' syntax, e.g. 'PVC板(昆明,8mm)'."
        )

{
    "type": "object",
    "properties": {
        "skill_name": {
            "type": "string",
            "description": "Name of the skill from the skill index in your instructions, e.g. 'AI Skill Operations'."
        }
    },
    "required": ["skill_name"]
}
